import 'package:flutter/material.dart'; import 'package:flutter_riverpod/flutter_riverpod.dart'; import 'package:go_router/go_router.dart'; import '../crm_providers.dart';
class WhatsAppAgentScreen extends ConsumerWidget { const WhatsAppAgentScreen({super.key}); @override Widget build(BuildContext c,WidgetRef r){final q=r.watch(whatsappIntegrationProvider);final repo=r.read(crmInboxRepositoryProvider);return Scaffold(appBar:AppBar(title:const Text('WhatsApp Agent')),body:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('WhatsApp Agent',style:Theme.of(c).textTheme.headlineSmall),const SizedBox(height:12),const Text('Grounded in Business Brain with human takeover support.'),const SizedBox(height:20),FutureBuilder(future:repo.agent(),builder:(c,s){if(!s.hasData)return const LinearProgressIndicator();final agent=s.data!;return Card(child:ListTile(title:Text(agent.active?'Active':'Paused'),subtitle:Text(agent.active?'The WhatsApp Agent can automatically respond to eligible WhatsApp conversations.':'The WhatsApp Agent will not automatically process new eligible customer messages.'),trailing:FilledButton(onPressed:()async{await repo.setAgentStatus(agent.active?'paused':'active');},child:Text(agent.active?'Pause Agent':'Activate Agent'))));}),q.when(loading:()=>const LinearProgressIndicator(),error:(e,_)=>Text('Integration unavailable: $e'),data:(x){final connected=x?['status']=='connected';return Card(child:ListTile(leading:Icon(connected?Icons.check_circle:Icons.warning,color:connected?Colors.green:Colors.orange),title:Text(connected?'Connected':'WhatsApp not configured'),subtitle:Text(connected?'WhatsApp integration is available.':'Meta WhatsApp configuration is required before live conversations can be sent or received.')));}),const SizedBox(height:12),Wrap(spacing:8,children:[for(final item in {'Company Profile':'/business-brain/company-profile','Business Hours':'/business-brain/hours','Services':'/business-brain/services','FAQs':'/business-brain/knowledge','Policies':'/business-brain/policies','Customer Engagement':'/business-brain/engagement','Documents':'/business-brain/documents'}.entries)ActionChip(label:Text(item.key),onPressed:()=>c.go(item.value))])]),));}}
